#define MOD 1000000007

typedef struct {
    int to, next;
} Edge;

Edge edges[200005];
int head[100005], idx = 0;

int up[100005][18];
int depth[100005];
int N, M;

long long dp[100005][2];
int constraint[100005]; // highest (deepest) constraint endpoint in subtree

void add_edge(int u, int v) {
    edges[idx].to = v;
    edges[idx].next = head[u];
    head[u] = idx++;
}

void dfs_lca(int u, int p) {
    up[u][0] = p;
    depth[u] = (p == -1) ? 0 : depth[p] + 1;
    for (int j = 1; j < 18; j++) {
        if (up[u][j-1] != -1)
            up[u][j] = up[up[u][j-1]][j-1];
        else
            up[u][j] = -1;
    }
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == p) continue;
        dfs_lca(v, u);
    }
}

int lca(int u, int v) {
    if (depth[u] < depth[v]) {
        int tmp = u; u = v; v = tmp;
    }
    int diff = depth[u] - depth[v];
    for (int j = 0; j < 18; j++)
        if (diff & (1 << j))
            u = up[u][j];
    if (u == v) return u;
    for (int j = 17; j >= 0; j--) {
        if (up[u][j] != up[v][j]) {
            u = up[u][j];
            v = up[v][j];
        }
    }
    return up[u][0];
}

void dfs_dp(int u, int p) {
    dp[u][0] = 1;
    dp[u][1] = 0;
    for (int i = head[u]; i != -1; i = edges[i].next) {
        int v = edges[i].to;
        if (v == p) continue;
        dfs_dp(v, u);
        long long new0 = (dp[u][0] * (dp[v][0] + dp[v][1])) % MOD;
        long long new1 = (dp[u][1] * (dp[v][0] + dp[v][1]) + dp[u][0] * dp[v][1]) % MOD;
        dp[u][0] = new0;
        dp[u][1] = new1;
    }
    if (constraint[u] != 0) {
        // must have at least one black on path up to constraint[u]
        // but we handle by forcing that the edge above is black if constraint not satisfied in children
        // Actually simpler: dp[u][0] = 0 if there's a constraint ending at u
        dp[u][0] = 0;
    }
}

int main() {
    scanf("%d %d", &N, &M);
