        int w = lca(u, v);
        // Mark that path from u to w and v to w must have black edge
        // We'll store constraint at the deeper endpoints
        if (depth[u] > depth[w]) {
            if (constraint[u] == 0 || depth[constraint[u]] < depth[w])
                constraint[u] = w;
        }
        if (depth[v] > depth[w]) {
            if (constraint[v] == 0 || depth[constraint[v]] < depth[w])
                constraint[v] = w;
        }
    }
    dfs_dp(1, -1);
    printf("%lld\n", dp[1][1] % MOD);
    return 0;
}

