void dfs(int node, int parent, int target, long long cur_mask, long long *result, int *found) {
    if (node == target) { *result = cur_mask; *found = 1; return; }
    for (int i = 1; i <= N; i++) {
        if (adj[node][i] && i != parent) {
            long long new_mask = cur_mask | (1LL << edge_id[node][i]);
            dfs(i, node, target, new_mask, result, found);
            if (*found) return;
        }
    }
}

int main() {
    scanf("%d %d", &N, &M);
    for (int i = 0; i < N-1; i++) {
        int a, b; scanf("%d %d", &a, &b);
        adj[a][b] = adj[b][a] = 1;
        edge_id[a][b] = edge_id[b][a] = i;
    }
    for (int i = 0; i < M; i++) {
        scanf("%d %d", &u_r[i], &v_r[i]);
        long long res = 0; int found = 0;
        dfs(u_r[i], -1, v_r[i], 0, &res, &found);
        path_mask[i] = res;
    }

    long long ans = 0;
    for (int S = 0; S < (1 << M); S++) {
        long long union_mask = 0;
        int bits = __builtin_popcount(S);
        for (int i = 0; i < M; i++) {
            if (S & (1 << i)) union_mask |= path_mask[i];
        }
        int k = __builtin_popcountll(union_mask);
        long long ways = 1LL << (N - 1 - k);
        if (bits % 2 == 0) ans += ways;
        else ans -= ways;
    }
    printf("%lld\n", ans);
    return 0;
}

