typedef long long ll;

typedef struct Edge {
    int to, id, next;
} Edge;

int main(void) {
    int N;
    if (scanf("%d", &N) != 1) return 0;

    int E = N - 1;
    int *ea = (int *)malloc(E * sizeof(int));
    int *eb = (int *)malloc(E * sizeof(int));

    Edge *g = (Edge *)malloc((2 * E) * sizeof(Edge));
    int *head = (int *)malloc((N + 1) * sizeof(int));
    for (int i = 1; i <= N; i++) head[i] = -1;

    int ptr = 0;
    for (int i = 0; i < E; i++) {
        int a, b;
        scanf("%d %d", &a, &b);
        ea[i] = a;
        eb[i] = b;

        g[ptr].to = b;
        g[ptr].id = i;
        g[ptr].next = head[a];
        head[a] = ptr++;

        g[ptr].to = a;
        g[ptr].id = i;
        g[ptr].next = head[b];
        head[b] = ptr++;
    }

    int M;
    scanf("%d", &M);

    int *u = (int *)malloc(M * sizeof(int));
    int *v = (int *)malloc(M * sizeof(int));
    for (int i = 0; i < M; i++) scanf("%d %d", &u[i], &v[i]);

    /* Root tree at 1, compute parent and parent-edge */
    int *parent = (int *)malloc((N + 1) * sizeof(int));
    int *pedge = (int *)malloc((N + 1) * sizeof(int));
    int *stack = (int *)malloc(N * sizeof(int));
    int top = 0;
    stack[top++] = 1;
    parent[1] = 0;
    pedge[1] = -1;

    for (int i = 0; i < top; i++) {
        int x = stack[i];
        for (int e = head[x]; e != -1; e = g[e].next) {
            int y = g[e].to;
            if (y == parent[x]) continue;
            parent[y] = x;
            pedge[y] = g[e].id;
            stack[top++] = y;
        }
    }

    /* For each restriction, build bitmask of edges on the path */
    unsigned long long *pathmask = (unsigned long long *)malloc(M * sizeof(unsigned long long));

    for (int i = 0; i < M; i++) {
        unsigned long long mask = 0ULL;
        int x = u[i], y = v[i];

        while (x != y) {
            if (x > y) {
                mask |= (1ULL << pedge[x]);
                x = parent[x];
            } else {
                mask |= (1ULL << pedge[y]);
                y = parent[y];
            }
        }
        pathmask[i] = mask;
    }

    /* Inclusion-Exclusion:
       Let A_i = colorings where path i is all white.
       Need total - union A_i.
    */
    ll ans = 0;
    int total_sub = 1 << M;

    for (int s = 0; s < total_sub; s++) {
        unsigned long long used = 0ULL;
        int bits = 0;
        for (int i = 0; i < M; i++) {
            if (s & (1 << i)) {
                used |= pathmask[i];
                bits++;
            }
        }

        int forced_white = 0;
        for (int i = 0; i < E; i++) {
            if (used & (1ULL << i)) forced_white++;
        }

        ll ways = 1LL << (E - forced_white);
        if (bits % 2 == 0) ans += ways;
        else ans -= ways;
    }

    printf("%lld\n", ans);

    free(ea);
    free(eb);
    free(g);
    free(head);
    free(u);
    free(v);
    free(parent);
    free(pedge);
    free(stack);
    free(pathmask);

    return 0;
}

