const int MOD = 1e9+7;

int modpow(int a, int e) {
    int r = 1;
    while(e) {
        if(e & 1) r = 1LL * r * a % MOD;
        a = 1LL * a * a % MOD;
        e >>= 1;
    }
    return r;
}

