    vector<int> parent(N, -1);

    function<void(int,int)> dfs = [&](int u, int p) {
        parent[u] = p;
        for (int v : g[u]) {
            if (v == p) continue;
            depth[v] = depth[u] + 1;
            up[v][0] = u;
            for (int j = 1; j < LOG; j++) {
                if (up[v][j-1] != -1)
                    up[v][j] = up[up[v][j-1]][j-1];
            }
            dfs(v, u);
        }
    };
    dfs(0, -1);

    auto lca = [&](int u, int v) {
        if (depth[u] < depth[v]) swap(u, v);
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; j++) {
            if (diff & (1<<j)) u = up[u][j];
        }
        if (u == v) return u;
        for (int j = LOG-1; j >= 0; j--) {
            if (up[u][j] != up[v][j]) {
                u = up[u][j];
                v = up[v][j];
            }
        }
        return parent[u];
    };

    // Map each edge to an index
    vector<int> edgeIdx(N, -1);
    for (int i = 0; i < N-1; i++) {
        auto [a,b] = edges[i];
        if (parent[b] == a) edgeIdx[b] = i;
        else edgeIdx[a] = i;
    }

    vector<pair<int,int>> restrictions(M);
    for (int i = 0; i < M; i++) {
        int u, v;
        cin >> u >> v;
        u--; v--;
        restrictions[i] = {u, v};
    }

    int ans = 0;
    // inclusion-exclusion
    for (int mask = 0; mask < (1<<M); mask++) {
        vector<bool> forced(N-1, false);
        bool bad = false;
        int cnt = 0;
        for (int i = 0; i < M; i++) {
            if (mask & (1<<i)) {
                auto [u, v] = restrictions[i];
                int w = lca(u, v);
                // mark edges on path u->w
                while (u != w) {
                    int idx = edgeIdx[u];
                    if (forced[idx]) { /* already forced, fine */ }
                    else { forced[idx] = true; cnt++; }
                    u = parent[u];
                }
                while (v != w) {
                    int idx = edgeIdx[v];
                    if (forced[idx]) { /* already forced */ }
                    else { forced[idx] = true; cnt++; }
                    v = parent[v];
                }
            }
        }
        if (bad) continue;
        int freeEdges = (N-1) - cnt;
        int ways = modpow(2, freeEdges);
        if (__builtin_popcount(mask) % 2 == 0) {
            ans = (ans + ways) % MOD;
        } else {
            ans = (ans - ways + MOD) % MOD;
        }
    }

    cout << ans << "\n";
    return 0;
}

