const int MAXN = 100005, LOG = 17;
vector<int> adj[MAXN];
int depth[MAXN], par[MAXN][LOG], tin[MAXN], timer_=0;
int N, M;

void dfs(int u, int p, int d) {
    par[u][0] = p; depth[u] = d; tin[u] = timer_++;
    for (int v : adj[u]) if (v != p) dfs(v, u, d+1);
}

int lca(int u, int v) {
    if (depth[u] < depth[v]) swap(u,v);
    int diff = depth[u]-depth[v];
    for (int i=0;i<LOG;i++) if ((diff>>i)&1) u=par[u][i];
    if (u==v) return u;
    for (int i=LOG-1;i>=0;i--) if (par[u][i]!=par[v][i]) {u=par[u][i];v=par[v][i];}
    return par[u][0];
}

int dist(int u, int v) { return depth[u]+depth[v]-2*depth[lca(u,v)]; }

