        if (nodes.empty()){ans+=1LL<<(N-1);continue;}
        sort(nodes.begin(),nodes.end(),[](int a,int b){return tin[a]<tin[b];});
        nodes.erase(unique(nodes.begin(),nodes.end()),nodes.end());
        int sz=nodes.size(); long long s=0;
        for (int i=0;i<sz-1;i++) s+=dist(nodes[i],nodes[i+1]);
        s+=dist(nodes[sz-1],nodes[0]);
        s/=2;
        int bits=__builtin_popcount(mask);
        long long ways=(N-1-s>=0)?(1LL<<(N-1-s)):0;
