#include <bits/stdc++.h>
using namespace std;

using ll = long long;

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int N;
    cin >> N;

    vector<vector<pair<int,int>>> g(N);
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        --a; --b;
        g[a].push_back({b, i});
        g[b].push_back({a, i});
    }

    int M;
    cin >> M;
    vector<int> masks(M, 0);

    // Since this problem is intended for small M (inclusion-exclusion),
    // we encode for each restriction the set of edges on its path.
    for (int i = 0; i < M; i++) {
        int u, v;
        cin >> u >> v;
        --u; --v;

        vector<int> parent(N, -1), parentEdge(N, -1);
        queue<int> q;
        q.push(u);
        parent[u] = u;

        while (!q.empty()) {
            int x = q.front();
            q.pop();
            if (x == v) break;
            for (auto [to, eid] : g[x]) {
                if (parent[to] == -1) {
                    parent[to] = x;
                    parentEdge[to] = eid;
                    q.push(to);
                }
            }
        }

        int cur = v;
        int mask = 0;
        while (cur != u) {
            mask |= (1 << parentEdge[cur]);
            cur = parent[cur];
        }
        masks[i] = mask;
    }

    ll ans = 0;
    for (int s = 0; s < (1 << M); s++) {
        int used = 0;
        int bits = 0;
        for (int i = 0; i < M; i++) {
            if (s >> i & 1) {
                used |= masks[i];
                bits++;
            }
        }

        int cnt = __builtin_popcount((unsigned)used);
        ll ways = 1LL << ((N - 1) - cnt);

        if (bits % 2 == 0) ans += ways;
        else ans -= ways;
    }

    cout << ans << '\n';
    return 0;
}

