import java.util.*;

public class Main {
    static final int MOD = 1_000_000_007;
    static List<Integer>[] tree;
    static List<Integer>[] upQueries;
    static int[] depth;
    static int[][] parent;
    static int LOG;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringTokenizer st = new StringTokenizer(br.readLine());
        int N = Integer.parseInt(st.nextToken());
        int M = Integer.parseInt(st.nextToken());

        tree = new ArrayList[N+1];
        upQueries = new ArrayList[N+1];
        for (int i = 1; i <= N; i++) {
            tree[i] = new ArrayList<>();
            upQueries[i] = new ArrayList<>();
        }

        for (int i = 0; i < N-1; i++) {
            st = new StringTokenizer(br.readLine());
            int a = Integer.parseInt(st.nextToken());
            int b = Integer.parseInt(st.nextToken());
            tree[a].add(b);
            tree[b].add(a);
        }

        LOG = (int)(Math.log(N)/Math.log(2)) + 1;
        parent = new int[N+1][LOG];
        depth = new int[N+1];

        // LCA prep
        dfs(1, 0);

        for (int i = 0; i < M; i++) {
            st = new StringTokenizer(br.readLine());
            int u = Integer.parseInt(st.nextToken());
            int v = Integer.parseInt(st.nextToken());
            int lca = lca(u, v);
            upQueries[u].add(lca);
            upQueries[v].add(lca);
        }

        long[] res = dfs2(1, 0);
        System.out.println(res[0]);
    }

    static void dfs(int u, int p) {
        parent[u][0] = p;
        for (int j = 1; j < LOG; j++) {
            parent[u][j] = parent[parent[u][j-1]][j-1];
        }
        for (int v : tree[u]) {
            if (v != p) {
                depth[v] = depth[u] + 1;
                dfs(v, u);
            }
        }
    }

    static int lca(int u, int v) {
        if (depth[u] < depth[v]) {
            int tmp = u; u = v; v = tmp;
        }
        int diff = depth[u] - depth[v];
        for (int j = 0; j < LOG; j++) {
            if ((diff & (1 << j)) != 0) {
                u = parent[u][j];
            }
        }
        if (u == v) return u;
        for (int j = LOG-1; j >= 0; j--) {
            if (parent[u][j] != parent[v][j]) {
                u = parent[u][j];
                v = parent[v][j];
            }
        }
        return parent[u][0];
    }

    static long[] dfs2(int u, int p) {
        // dp[0] = ways where no pending unsatisfied restriction goes above u
        // dp[1] = ways where at least one unsatisfied restriction goes above u
        long dp0 = 1, dp1 = 0;

        for (int v : tree[u]) {
            if (v == p) continue;
            long[] child = dfs2(v, u);
            long c0 = dp0, c1 = dp1;
            // combine: edge (u,v) can be white or black
            // child[0] -> all satisfied below v
            // child[1] -> there is pending requirement from v's subtree
            // If we set edge white, child[1] cannot happen (needs black)
            // If we set edge black, both child states are ok.
            dp0 = (c0 * ((child[0] + child[1]) % MOD) % MOD + c1 * child[0] % MOD) % MOD;
            dp1 = (c0 * child[1] % MOD + c1 * ((child[0] + child[1]) % MOD) % MOD) % MOD;
        }

        // Process queries ending at u (going upwards)
        for (int lcaNode : upQueries[u]) {
            if (lcaNode == u) {
                // This means the other endpoint is in subtree, so it's already fully inside.
                // That restriction is already satisfied if any edge on path is black
                // but the DP already covers it correctly.
                // However, if u == lca and u != the other endpoint, 
                // the restriction is from u downwards only -> handled in child DP.
            } else {
                // This restriction goes upward from u to lcaNode (or further)
                // If the edge to parent is white, this restriction fails.
                // So we must force the edge to parent to be black.
                // We set dp0 = 0 (cannot have no pending upward) if this is the deepest such?
                // Actually, we track that some pending exists: set dp0 = 0, dp1 stays.
                dp0 = 0;
            }
        }

        return new long[]{dp0 % MOD, (dp0 + dp1) % MOD};
    }
}

