    static int[][] up;
    static List<int[]>[] adj;
    static int LOG = 17, timer = 0;

    public static void main(String[] args) throws IOException {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        int N = Integer.parseInt(br.readLine().trim());
        adj = new List[N+1];
        for(int i=1;i<=N;i++) adj[i] = new ArrayList<>();
        for(int i=0;i<N-1;i++){
            StringTokenizer st = new StringTokenizer(br.readLine());
            int a=Integer.parseInt(st.nextToken()), b=Integer.parseInt(st.nextToken());
            adj[a].add(new int[]{b,i}); adj[b].add(new int[]{a,i});
        }
        int M = Integer.parseInt(br.readLine().trim());
        int[] U=new int[M], V=new int[M];
        for(int i=0;i<M;i++){
            StringTokenizer st = new StringTokenizer(br.readLine());
            U[i]=Integer.parseInt(st.nextToken()); V[i]=Integer.parseInt(st.nextToken());
        }
        depth=new int[N+1]; tin=new int[N+1]; up=new int[LOG][N+1];
        dfs(1,0,0);
        long ans=0;
        for(int mask=0;mask<(1<<M);mask++){
            List<Integer> pts=new ArrayList<>();
            for(int i=0;i<M;i++) if((mask>>i&1)>0){pts.add(U[i]);pts.add(V[i]);}
            if(pts.isEmpty()){ans+=1L<<(N-1);continue;}
            pts.sort((a,b)->tin[a]-tin[b]);
            int sz=pts.size(); long edgeCount=0;
            for(int i=0;i<sz;i++) edgeCount+=dist(pts.get(i),pts.get((i+1)%sz));
            edgeCount/=2;
            int bits=Integer.bitCount(mask);
            ans+=(bits%2==0?1:-1)*(1L<<(N-1-edgeCount));
        }
        System.out.println(ans);
    }
    static void dfs(int v,int p,int d){
        depth[v]=d; tin[v]=timer++; up[0][v]=p;
        for(int i=1;i<LOG;i++) up[i][v]=up[i-1][up[i-1][v]];
        for(int[] e:adj[v]) if(e[0]!=p) dfs(e[0],v,d+1);
    }
    static int lca(int a,int b){
        if(depth[a]<depth[b]){int t=a;a=b;b=t;}
        int diff=depth[a]-depth[b];
        for(int i=0;i<LOG;i++) if((diff>>i&1)>0) a=up[i][a];
        if(a==b) return a;
        for(int i=LOG-1;i>=0;i--) if(up[i][a]!=up[i][b]){a=up[i][a];b=up[i][b];}
        return up[0][a];
    }
    static int dist(int a,int b){return depth[a]+depth[b]-2*depth[lca(a,b)];}
}

import java.io.*;
import java.util.*;

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        int nextInt() throws IOException {
            int c;
            do {
                c = read();
            } while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            int val = 0;
            while (c > ' ') {
                val = val * 10 + (c - '0');
                c = read();
            }
            return val * sign;
        }
    }

    static class Edge {
        int to, idx;
        Edge(int to, int idx) {
            this.to = to;
            this.idx = idx;
        }
    }

    static int N, M;
    static ArrayList<Edge>[] g;
    static int[] parent, parentEdge, depth;

    static void dfs(int root) {
        int[] stack = new int[N];
        int sp = 0;
        stack[sp++] = root;
        parent[root] = -1;
        depth[root] = 0;

        while (sp > 0) {
            int v = stack[--sp];
            for (Edge e : g[v]) {
                if (e.to == parent[v]) continue;
                parent[e.to] = v;
                parentEdge[e.to] = e.idx;
                depth[e.to] = depth[v] + 1;
                stack[sp++] = e.to;
            }
        }
    }

    static long pathMask(int u, int v) {
        long mask = 0L;
        while (depth[u] > depth[v]) {
            mask |= 1L << parentEdge[u];
            u = parent[u];
        }
        while (depth[v] > depth[u]) {
            mask |= 1L << parentEdge[v];
            v = parent[v];
        }
        while (u != v) {
            mask |= 1L << parentEdge[u];
            mask |= 1L << parentEdge[v];
            u = parent[u];
            v = parent[v];
        }
        return mask;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();
        N = fs.nextInt();
        g = new ArrayList[N];
        for (int i = 0; i < N; i++) g[i] = new ArrayList<>();

        for (int i = 0; i < N - 1; i++) {
            int a = fs.nextInt() - 1;
            int b = fs.nextInt() - 1;
            g[a].add(new Edge(b, i));
            g[b].add(new Edge(a, i));
        }

        M = fs.nextInt();
        int[] u = new int[M];
        int[] v = new int[M];
        for (int i = 0; i < M; i++) {
            u[i] = fs.nextInt() - 1;
            v[i] = fs.nextInt() - 1;
        }

        parent = new int[N];
        parentEdge = new int[N];
        depth = new int[N];
        dfs(0);

        long[] condMask = new long[M];
        for (int i = 0; i < M; i++) {
            condMask[i] = pathMask(u[i], v[i]);
        }

        long ans = 0;
        int totalSubsets = 1 << M;

        for (int s = 0; s < totalSubsets; s++) {
            long unionMask = 0L;
            int bits = 0;
            for (int i = 0; i < M; i++) {
                if (((s >> i) & 1) == 1) {
                    unionMask |= condMask[i];
                    bits++;
                }
            }
            int covered = Long.bitCount(unionMask);
            long ways = 1L << (N - 1 - covered);
            if ((bits & 1) == 0) ans += ways;
            else ans -= ways;
        }

        System.out.println(ans);
    }
}

import sys
sys.setrecursionlimit(1 << 20)

MOD = 10**9 + 7

def solve():
    input = sys.stdin.readline
    N, M = map(int, input().split())
    g = [[] for _ in range(N)]
    edges = []
    for _ in range(N - 1):
        a, b = map(int, input().split())
        a -= 1
        b -= 1
        g[a].append(b)
        g[b].append(a)
        edges.append((a, b))

    # LCA preparation
    LOG = (N).bit_length()
    parent = [[-1] * N for _ in range(LOG)]
    depth = [0] * N
    # root at 0
    stack = [(0, -1)]
    order = []
    while stack:
        v, p = stack.pop()
        if v >= 0:
            order.append(v)
            parent[0][v] = p
            for to in g[v]:
                if to == p: continue
                depth[to] = depth[v] + 1
                stack.append((to, v))
        # else: nothing
    for k in range(1, LOG):
        for v in range(N):
            if parent[k-1][v] != -1:
                parent[k][v] = parent[k-1][parent[k-1][v]]

    def lca(u, v):
        if depth[u] < depth[v]:
            u, v = v, u
        # lift u
        diff = depth[u] - depth[v]
        for k in range(LOG):
            if diff >> k & 1:
                u = parent[k][u]
        if u == v:
            return u
        for k in reversed(range(LOG)):
            if parent[k][u] != parent[k][v]:
                u = parent[k][u]
                v = parent[k][v]
        return parent[0][u]

    # map edge to child node
    edge_to_child = {}
    for idx, (a, b) in enumerate(edges):
        if depth[a] < depth[b]:
            a, b = b, a
        edge_to_child[a] = idx  # node 'a' is child

    # difference array for bitmask on nodes
    diff = [0] * N
    restrictions = []
    for i in range(M):
        u, v = map(int, input().split())
        u -= 1
        v -= 1
        restrictions.append((u, v))
        w = lca(u, v)
        diff[u] |= (1 << i)
        diff[v] |= (1 << i)
        diff[w] ^= (1 << i)  # cancel double count at LCA
        if parent[0][w] != -1:
            diff[parent[0][w]] ^= (1 << i)

    # propagate from leaves to root
    mask_of_edge = [0] * (N - 1)
    for v in reversed(order):
        for to in g[v]:
            if to == parent[0][v]:
                continue
            diff[v] ^= diff[to]
        if v != 0:
            eid = edge_to_child[v]
            mask_of_edge[eid] = diff[v]

    cnt = [0] * (1 << M)
    for mask in mask_of_edge:
        cnt[mask] += 1

    # precompute pow2
    pow2 = [1] * (N + 1)
    for i in range(1, N + 1):
        pow2[i] = (pow2[i-1] * 2) % MOD

    ans = 0
    for s in range(1 << M):
        forced = 0
        for mask in range(1 << M):
            if mask & s == 0:
                forced += cnt[mask]
        ways = pow2[N - 1 - forced]
        if bin(s).count("1") % 2 == 0:
            ans = (ans + ways) % MOD
        else:
            ans = (ans - ways) % MOD
    print(ans % MOD)

if __name__ == "__main__":
    solve()
